INSERT INTO user (email, password, phone, user_name, user_type)
VALUES (#{email}
		, #{password}
		, #{phone}
		, #{userName}
		, #{userType})

INSERT INTO USER_PERSON (user_id, birth_date, gender, country, pass_count, report_received_count)
VALUES (#{userId}
		, #{birthDate}
		, #{gender}
		, #{country}
		, 0
		, 0
    	
)

INSERT INTO USER_COMPANY (user_id, biz_reg_no, company_name, ceo_name, company_address)
VALUES (#{userId}
		, #{bizRegNo}
		, #{companyName}
		, #{ceoName}
		, #{companyAddress}
    	
)

